func (r *subagentRouter) observe(ev *msg.Event) {
	if ev.Type != msg.EventSystem || ev.System == nil {
		return
	}
	switch ev.System.Subtype {
	case "task_started":
		if ev.System.ToolUseID == "" || ev.System.TaskID == "" {
